def find_border_connected(grid, start_r, start_c, target_val):
    """Find all cells connected to the starting cell via same-value path"""
    nr, nc = len(grid), len(grid[0])
    visited = set()
    stack = [(start_r, start_c)]
    result = []

    while stack:
        r, c = stack.pop()
        if (r,c) in visited:
            continue
        visited.add((r,c))
        if grid[r][c] == target_val:
            result.append((r,c))

        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
