import os, re

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

def get_components(grid, connectivity='orthogonal'):
    """Return list of sets of positions, each set being a connected component"""
    visited = set()
    components = []

    def neighbors(pos):
        r, c = pos
        if connectivity == 'orthogonal':
            return [(r-1,c), (r+1,c), (r,c-1), (r,c+1)]
        else:  # diagonal
            return [(r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1)]

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0 and (r,c) not in visited:
                comp = {(r,c)}
                stack = [(r,c)]
                while stack:
                    curr = stack.pop()
                    for nr, nc in neighbors(curr):
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
                            if grid[nr][nc] != 0 and (nr,nc) not in visited and (nr,nc) not in comp:
                                comp.add((nr,nc))
                                stack.append((nr,nc))
                visited.update(comp)
                components.append(comp)
    return components

